"""Build the three existing public demos from the captured Adrian homepage structure.

All variants intentionally share one design, per the latest user direction.
Run: python3 build-exact.py. No external runtime assets or dependencies.
"""
from pathlib import Path
import json, shutil, re

ROOT=Path(__file__).resolve().parent
VERSION='adrian-structure-20261103'
P=json.loads((ROOT/'source/products.js').read_text().split('window.SAPONINE_PRODUCTS=')[1].rstrip(';\n'))

def icon(name): return f'<span class="icon icon-{name}" aria-hidden="true"></span>'
def logo(): return '<a class="brand-logo" href="#home" aria-label="ساپونین، صفحه اصلی"><img src="assets/saponine-logo.png" alt="Saponine Pharmaceutical Company" width="735" height="519"></a>'
def img(i,cls='',eager=False):
    p=P[i]
    return f'<img src="{p["image"]}" class="{cls}'+(' wide' if i==4 else '')+f'" alt="{p["name"]}" width="1536" height="1024" '+('fetchpriority="high"' if eager else 'loading="lazy"')+'>'
def circles():
    spans=''.join(f'<span class="circle-w circle-w{i}"><span class="circle"></span></span>' for i in range(1,5))
    return f'<div class="reference-circles left" aria-hidden="true">{spans}</div><div class="reference-circles right" aria-hidden="true"><div class="inner">{spans}</div></div>'
def head(title,sub): return f'<div class="section-head"><h2>{title}</h2><p>{sub}</p></div>'
def feature(title,sub,asset):return f'<div class="feature-item"><div><h3>{title}</h3><p>{sub}</p></div><span class="feature-symbol"><img src="assets/feature-{asset}.svg" alt="" width="48" height="48"></span></div>'

header=f'''<a class="skip" href="#features">رفتن به محتوای اصلی</a>
<header class="site-header"><div class="header-inner">{logo()}
<nav class="desktop-nav" aria-label="منوی اصلی"><button class="mega-toggle" id="megaToggle" aria-expanded="false" aria-controls="megaMenu">برندهای ساپونین</button><button data-catalog>محصولات</button><a href="#about">درباره ما</a><a href="#contact">تماس با ما</a></nav>
<div class="header-tools"><button class="search-trigger" id="searchOpen" aria-label="جستجوی محصولات">{icon('search')}</button><a class="btn header-cta" href="#pharmacies">داروخانه‌ها</a></div>
<button class="menu-toggle" id="menuToggle" aria-label="باز کردن منو" aria-expanded="false" aria-controls="mobileNav"><img src="assets/icons/menu.svg" alt=""></button></div>
<div class="mega" id="megaMenu" hidden>{''.join(f'<a href="#products" data-select-product="{i}">{img(i)}<span><strong>{p["short"]}</strong><small>{p["en"]}</small></span></a>' for i,p in enumerate(P))}</div>
<nav class="mobile-nav" id="mobileNav" aria-label="منوی موبایل" hidden><a href="#brands">برندهای ساپونین</a><button data-catalog>محصولات</button><a href="#about">درباره ما</a><a href="#contact">تماس با ما</a><a href="#pharmacies">داروخانه‌ها</a><button data-search>جستجو {icon('search')}</button><details><summary>صفحات اختصاصی</summary><a href="#cooperation" data-contact>فرم همکاری با ما</a><a href="#faq" data-faq>سوالات متداول</a></details></nav></header>'''

sections=[('home','SLIDER','اسلایدر'),('features','FEATURES','رویکرد ساپونین'),('brands','BRANDS','برندهای ما'),('about','ABOUT US','درباره ما'),('products','PRODUCTS','محصولات'),('pharmacies','PHARMACIES','داروخانه‌ها'),('contact','CONTACT','تماس با ما')]
rail='<nav class="section-rail" aria-label="پیمایش بخش‌های صفحه">'+''.join(f'<a class="rail-link{" active" if i==0 else ""}" href="#{key}" aria-label="{fa}"'+(' aria-current="step"' if i==0 else '')+f'><span>{en}</span></a>' for i,(key,en,fa) in enumerate(sections))+'</nav>'
photos=['hair','hands','laboratory','water','lifestyle']
alts=['پرتره واقعی در فضای باز و مراقبت از مو','شست‌وشوی دست‌ها با آب و صابون','پژوهشگر در یک آزمایشگاه؛ عکس آرشیوی','بازتاب نور خورشید بر آب زلال','پیاده‌روی در فضای سبز']
heroNames=['Sapo-Zinc','Bibacter','Povidone','Permethrin','Vitamin B1']
taglines=['Care, every day','A caring touch','Care in detail','A fresh perspective','Life in motion']
authors=['Nyana Stoica','Claudio Schwarz','NIAID','Lee Jeffs','Vitaly Gariev']
urls=['https://unsplash.com/photos/woman-holding-her-hair-I6K5ZSAfJDk','https://unsplash.com/photos/washing-hands-with-soap-muq_ej7p9s0','https://unsplash.com/photos/a-woman-in-a-lab-looking-through-a-microscope-cK0hjNSgnS4','https://unsplash.com/photos/blue-swimming-pool-water-ripples-60wCqYf7Fg8','https://unsplash.com/photos/couple-walking-outdoors-with-gym-bags-and-water-bottles-pxYDnXRPyQE']
slides=''
for i,p in enumerate(P):
    slides+=f'''<article class="hero-slide{' is-current' if i==0 else ''}" data-slide-index="{i}" aria-hidden="{'false' if i==0 else 'true'}"{' inert' if i else ''}><img class="hero-photograph" src="assets/slider-{photos[i]}.webp" alt="{alts[i]}" {'fetchpriority="high"' if i==0 else 'loading="lazy"'}><div class="hero-shade"></div><div class="hero-copy"><p class="hero-english">{heroNames[i]}</p><p class="hero-tagline">{taglines[i]}</p><p class="hero-persian">{p['name']}</p></div><button class="hero-pack-button" data-detail="{i}" aria-label="مشاهده {p['name']}">{img(i,'pack-image',True)}</button><a class="hero-credit" href="{urls[i]}" target="_blank" rel="noopener noreferrer">{authors[i]} / Unsplash</a></article>'''
hero=f'''<section id="home" class="page-panel hero is-active" aria-label="معرفی محصولات ساپونین" aria-roledescription="اسلایدر" data-active-slide="0"><h1 class="sr-only">شرکت داروسازی ساپونین ایران</h1><div class="hero-slides">{slides}</div><div class="hero-controls" aria-label="کنترل اسلایدر">{''.join(f'<button class="hero-dot" data-slide="{i}" aria-label="اسلاید {i+1}" aria-current="{str(i==0).lower()}"><span></span></button>' for i in range(5))}<button class="hero-play" id="heroPlay" aria-label="توقف پخش خودکار" aria-pressed="false">{icon('pause')}</button></div><button class="scroll-medallion" data-next-section aria-label="رفتن به بخش بعد"><img class="medallion-base" src="assets/reference-next-background.svg" alt=""><img class="medallion-ring" src="assets/reference-scroll-label.svg" alt=""><span>SAPONINE<br>PHARMA</span></button><p class="sr-only" id="heroStatus" role="status" aria-live="polite"></p></section>'''
features=f'''<section id="features" class="page-panel feature-panel" aria-label="رویکرد ساپونین"><div class="panel-content">{head('رویکردی که ما را متمایز می‌کند','دانش، کیفیت و مراقبت؛ در کنار هم')}<div class="features"><div class="feature-col">{feature('فرمولاسیون','توسعه محصول با تکیه بر دانش تخصصی','formula')}{feature('نگاه به سلامت','محصولات دارویی، بهداشتی و مکمل‌ها','care')}</div><div class="feature-center"><img class="feature-ring" src="assets/reference-feature-ring.svg" alt=""><span class="feature-word" aria-hidden="true">SAPONINE PHARMA</span>{img(0,'feature-pack')}</div><div class="feature-col">{feature('کنترل کیفیت','بررسی مواد در آزمایشگاه کنترل شرکت','quality')}{feature('شناخت آگاهانه','اطلاعات روشن و قابل پیگیری محصولات','trust')}</div></div></div></section>'''
brands=f'''<section id="brands" class="page-panel brands-panel" aria-label="برندهای ساپونین">{circles()}<div class="panel-content">{head('برندهای ما','هر محصول، یک تجربه متفاوت')}<div class="brand-grid">{''.join(f'<button class="brand-card" data-select-product="{i}"><span class="brand-mark">{img(i)}</span><h3>{p["short"]}</h3><p>{p["en"]}</p>{icon("arrow")}</button>' for i,p in enumerate(P))}</div><div class="section-action"><button class="btn" data-catalog>مشاهده همه محصولات {icon('arrow')}</button></div></div></section>'''
about=f'''<section id="about" class="page-panel about-panel" aria-label="درباره ساپونین">{circles()}<div class="story-ribbon" aria-hidden="true">{''.join(f'<img src="assets/slider-{photos[i%5]}.webp" alt="">' for i in range(7))}</div><div class="panel-content about-layout"><div class="about-copy">{head('داستان تولد یک برند','از یک آغاز ساده، تا خانواده‌ای از محصولات')}<p>داستان ساپونین ایران از سال ۱۳۶۸ و تولید صابون‌های طبی آغاز شد؛ مسیری که با اضافه‌شدن شامپوهای طبی و راه‌اندازی خط تولید مایعات ادامه یافت.</p><p>در گام بعد، بخش قرص‌سازی به این مجموعه افزوده شد و تولید مکمل‌های رژیمی و غذایی و شکل‌های دارویی در برنامه شرکت قرار گرفت.</p><p>امروز، ساپونین با استفاده از دانش متخصصان و بررسی مواد اولیه در آزمایشگاه کنترل شرکت، توسعه و تولید محصولات خود را دنبال می‌کند.</p><div class="about-actions"><button class="btn" id="aboutMore">درباره ما {icon('arrow')}</button><a class="btn outline" href="#contact">تماس با ما {icon('arrow')}</a></div></div><div class="about-media"><img src="assets/official-company.jpg" alt="تصویر شرکت از وب‌سایت رسمی ساپونین" loading="lazy"><button class="about-play" id="storyOpen" aria-label="نمایش معرفی تصویری ساپونین"><span>{icon('play')}</span></button></div></div></section>'''
products=f'''<section id="products" class="page-panel products-panel" aria-label="محصولات از نزدیک">{circles()}<div class="products-layout"><div class="orbit-wrap"><div class="product-orbit" id="productOrbit"><img class="orbit-ring" src="assets/reference-product-ring.svg" alt=""><div class="orbit-label" id="orbitLabel" aria-hidden="true"></div><button class="orbit-next" id="productNext" aria-label="محصول بعدی"></button><button class="orbit-prev" id="productPrevious" aria-label="محصول قبلی"></button>{''.join(f'<button class="orbit-item" data-orbit="{i}" aria-label="انتخاب {p["name"]}">{img(i)}</button>' for i,p in enumerate(P))}</div></div><div class="product-copy" aria-live="polite"><h2 id="productName"></h2><p class="product-en" id="productEnglish"></p><p class="product-description" id="productDescription"></p><button class="btn" id="productDetails">جزئیات محصول {icon('arrow')}</button></div><div class="product-facts" id="productFacts"></div></div></section>'''
pharmacies=f'''<section id="pharmacies" class="page-panel pharmacy-panel" aria-label="داروخانه‌ها">{circles()}<div class="panel-content pharmacy-layout"><div class="pharmacy-media"><div class="pill-column"><img src="assets/slider-laboratory.webp" alt="عکس آرشیوی پژوهشگر در آزمایشگاه" loading="lazy"></div><div class="pill-column"><img src="assets/official-company.jpg" alt="شرکت ساپونین" loading="lazy"></div></div><div class="pharmacy-copy"><h2>داروخانه‌ها</h2><p class="subtitle">مسیر ارتباط با ساپونین و آشنایی با محصولات</p><p>برای پیگیری موجودی محصولات و دریافت اطلاعات همکاری و توزیع، با دفتر شرکت ساپونین ایران در ارتباط باشید.</p><button class="btn" data-pharmacy>ارتباط با واحد فروش {icon('arrow')}</button></div></div></section>'''
footer=f'''<section id="contact" class="page-panel footer-panel" aria-label="تماس با ما"><footer class="panel-content"><div class="footer-box">{logo()}<nav class="footer-nav" aria-label="دسترسی سریع"><a href="#about">درباره ما</a><button data-contact>تماس با ما</button><button data-faq>سوالات متداول</button><button data-contact>فرم همکاری</button><button data-catalog>محصولات</button></nav><div class="footer-contact"><div>{icon('phone')}<span><strong>شماره تماس</strong><a href="tel:+982186030094" dir="ltr">۰۲۱–۸۶۰۳۰۰۹۴</a></span></div><div>{icon('mail')}<span><strong>ایمیل</strong><a href="mailto:info@saponine.com" dir="ltr">info@saponine.com</a></span></div><div>{icon('fax')}<span><strong>فکس</strong><span dir="ltr">۰۲۱–۸۶۰۳۱۸۷۶</span></span></div><div>{icon('map')}<span><strong>آدرس دفتر مرکزی</strong>تهران، سهروردی شمالی، خیابان شهید قندی، خیابان بیستم، پلاک ۵، واحد ۴</span></div></div></div><div class="footer-note"><p>ساپونین دارو ایران · شرکت داروسازی ساپونین ایران</p><a href="https://saponineco.com/" target="_blank" rel="noopener noreferrer">وب‌سایت رسمی ساپونین</a></div></footer></section>'''
dock='<nav class="product-dock" aria-label="دسترسی سریع محصولات">'+''.join(f'<button data-select-product="{i}"><span class="dock-image">{img(i)}</span>{p["short"]}</button>' for i,p in enumerate(P))+'</nav>'
tail=f'''{dock}<button class="motion-toggle" id="motionToggle" aria-label="کاهش حرکت" aria-pressed="false">{icon('pause')}</button><dialog id="dialog" aria-labelledby="dialogTitle"><button class="dialog-close" id="dialogClose" aria-label="بستن">{icon('close')}</button><div class="dialog-body" id="dialogBody"></div></dialog><div class="toast" id="toast" role="status" hidden></div><script src="products.js?v={VERSION}"></script><script src="app.js?v={VERSION}" defer></script>'''
body=header+rail+'<main id="main" tabindex="-1">'+hero+features+brands+about+products+pharmacies+footer+'</main>'+tail
asset_names=['feature-formula.svg','feature-care.svg','feature-quality.svg','feature-trust.svg','Baskervville-Regular.woff2','WebsimaIcon.woff','reference-next-background.svg','reference-scroll-label.svg','reference-feature-ring.svg','reference-product-ring.svg','reference-product-next.svg','reference-product-previous.svg','reference-decor.css']
for folder,css_name in [('source','styles.css'),('motion','style.css'),('reference','style.css')]:
    d=ROOT/folder
    for name in asset_names:
        if folder!='source':shutil.copy2(ROOT/'source/assets'/name,d/'assets'/name)
    (d/css_name).write_text((ROOT/'exact.css').read_text())
    (d/'app.js').write_text((ROOT/'exact.js').read_text())
    (d/'index.html').write_text(f'''<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#7d4697"><title>ساپونین دارو ایران | شرکت داروسازی ساپونین</title><meta name="description" content="آشنایی با شرکت داروسازی ساپونین ایران، محصولات و راه‌های ارتباط با شرکت."><link rel="preload" href="assets/IRANSans-Regular.woff" as="font" type="font/woff" crossorigin><link rel="stylesheet" href="{css_name}?v={VERSION}"><link rel="stylesheet" href="assets/reference-decor.css?v={VERSION}"></head><body data-build="{VERSION}" data-demo="{folder}">{body}</body></html>''')
    dest=ROOT/'dist'/folder
    shutil.copytree(d,dest,dirs_exist_ok=True)
    for device,w,h,scale in [('mobile',390,844,1),('tablet',834,1194,.72)]:
        (ROOT/'dist'/f'exact-{folder}-{device}.html').write_text(f'<!doctype html><title>{folder} {device} QA</title><style>body{{margin:0;background:#eaeaea;display:grid;place-items:start center}}iframe{{border:0;width:{w}px;height:{h}px;transform:scale({scale});transform-origin:top center}}</style><iframe title="{folder} {device}" src="{folder}/"></iframe>')
print('Built three matching Saponine sites:',VERSION)
